import{it as e,n as t,rt as n,vt as r}from"./chunks/framework.RzCcii2U.js";var i=JSON.parse(`{"title":"The RFC Process","description":"","frontmatter":{"title":"The RFC Process"},"headers":[],"relativePath":"guides/contributing/rfc-process.md","filePath":"guides/contributing/rfc-process.md"}`),a={name:`guides/contributing/rfc-process.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h3 id="requesting-features-or-deprecations" tabindex="-1">Requesting Features or Deprecations <a class="header-anchor" href="#requesting-features-or-deprecations" aria-label="Permalink to “Requesting Features or Deprecations”">​</a></h3><p>While WarpDrive is universal in nature, its development is managed by the EmberJS community.</p><p>WarpDrive participates in the <a href="https://github.com/emberjs/rfcs/" target="_blank" rel="noreferrer">RFC process (GitHub emberjs/rfcs)</a>. Most changes to the public API including new features, changes in behavior, or deprecations require community discussion and must go through this process.</p><p>While there is no guarantee that an RFC will be accepted, successful RFCs typically follow a pattern of iteration while gathering requirements, addressing feedback, and consensus building. The best RFCs are narrowly scoped with clear understanding of alternatives, drawbacks, and their effect on the community.</p><pre><code>Here are a few suggestions of **steps to take before drafting your RFC** to best make your RFC successful.
Often this process will complete quickly, but when it does not, don&#39;t despair! Often the best ideas
take the longest to bake.
</code></pre><ol><li>Bring up your idea on <a href="https://discord.gg/PHBbnWJx5S" target="_blank" rel="noreferrer">Discord</a> or with individual <a href="https://emberjs.com/team/" target="_blank" rel="noreferrer">team members</a></li><li>Reflect on any concerns, alternatives, or questions that arise from these discussions.</li><li>Continue to discuss the idea, giving time for everyone to digest and think about it.</li><li>Attend the weekly team meeting to discuss your idea</li><li>Open an <a href="https://github.com/emberjs/rfcs/issues?q=is%3Aissue+is%3Aopen+label%3AT-ember-data" target="_blank" rel="noreferrer">RFC issue</a> to broaden and record the discussion if the idea needs more time for discussion and iteration. <ul><li>label your issue with <code>T-ember-data</code> (or ask someone in <code>#dev-ember-data</code> to add the label if you lack the permission)</li><li>announce your issue in <code>#dev-ember-data</code> and anywhere else desired such as <code>#news-and-announcements</code> and <code>bluesky</code>.</li></ul></li><li><a href="https://github.com/emberjs/rfcs#what-the-process-is" target="_blank" rel="noreferrer">Draft an RFC</a> and share it with those you have been discussing the ideas with.</li><li>Publish your RFC by opening a PR to <a href="https://github.com/emberjs/rfcs/pulls?q=is%3Apr+is%3Aopen+label%3AT-ember-data" target="_blank" rel="noreferrer">emberjs/rfcs/</a><ul><li>label your PR with <code>T-ember-data</code> (or ask someone in <code>#dev-ember-data</code> to add the label if you lack the permission)</li><li>announce your PR in <code>#dev-ember-data</code> and anywhere else desired such as <code>#news-and-announcements</code> and <code>bluesky</code>.</li></ul></li><li>Attend weekly team meetings to discuss the RFC, continue iterating on the RFC, and help shepherd it to completion.</li><li>Build a proof-of-concept. Sometimes this is best if it occurs alongside drafting the RFC, as it often informs the RFC design, known drawbacks, and alternatives. Often it will become incorporated in the final implementation.</li><li>If you are able, help land the work in a release! It is not required that you implement your own RFC but often this is the best way to ensure that accepted RFCs are implemented in a timely manner.</li></ol>`,6)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};